import pathlib,json
p=pathlib.Path(__file__).parent
before=json.loads((p/'lod2-before.json').read_text());after=json.loads((p/'lod2-after.json').read_text());data=[]
for b,a in zip(before,after):
 data.append({'id':a['id'],'heapB':b['stages'][-1]['heapUsed']/1e6,'heapA':a['stages'][-1]['heapUsed']/1e6,'gpu':a['bytes']/1e6,'poses':[{'name':x['name'],'triB':x['triangles'],'triA':y['triangles'],'callsB':x['calls'],'callsA':y['calls']} for x,y in zip(b['poses'],a['poses'])]})
images={m:{pose:{label:f'/home/dev/terrain-lod2-evidence/lod2-{label}-{m}-{pose}.png' for label in ['before','after']} for pose in ['start','mid','overview']} for m in ['riviera','penteli','megara']}
for m in images:
 for pose in images[m]:images[m][pose]['overlay']=f'/home/dev/terrain-lod2-evidence/lod2-after-{m}-{pose}-debug.png'
html='''<!doctype html><html><head><meta charset="utf-8"><style>
*{box-sizing:border-box}body{margin:0;font-family:var(--font-sans,system-ui);color:var(--foreground);font-size:14px}p{margin:10px 0;color:var(--muted-foreground);line-height:1.45}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th,td{text-align:right;padding:9px 5px;border-bottom:1px solid var(--border)}th{font-size:12px;color:var(--muted-foreground);font-weight:500}th:first-child,td:first-child{text-align:left}td:first-child{text-transform:capitalize}strong{font-weight:650;color:var(--foreground)}.controls{display:flex;gap:6px;flex-wrap:wrap;margin:14px 0 8px}button{cursor:pointer;background:var(--secondary);color:var(--foreground);border:1px solid var(--border);border-radius:var(--radius,8px);padding:7px 12px;font:inherit;transition:background .15s,color .15s,border-color .15s}button[aria-pressed=true]{background:var(--primary);color:var(--primary-foreground);border-color:var(--primary)}.pair{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}figure{margin:0}img{display:block;width:100%;height:auto;border-radius:var(--radius,8px)}figcaption{margin-bottom:5px;font-size:12px;color:var(--muted-foreground)}.metric{padding:12px 16px;background:var(--secondary);border-radius:var(--radius,8px);margin:10px 0}.legend{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;color:var(--muted-foreground)}.legend span:before{content:'';display:inline-block;width:9px;height:9px;background:var(--c);margin-right:4px;border-radius:50%}.small{font-size:12px}@media(max-width:500px){th,td{padding:8px 3px;font-size:11px}.pair{grid-template-columns:1fr}.controls{gap:4px}button{padding:6px 9px;font-size:12px}}
</style></head><body>
<table><thead><tr><th>Map</th><th>Midpoint<br>triangles saved</th><th>Overview<br>triangles saved</th><th>JS heap MB<br>before → after</th><th>GPU geometry<br>MB after</th></tr></thead><tbody id="summary"></tbody></table>
<p class="small">Fresh-process heap after GC. GPU geometry remains compact; CPU-only LOD index storage is reported separately in the full results.</p>
<div class="controls" id="maps"></div><div class="controls" id="poses"></div>
<div class="metric" id="metric"></div>
<div class="controls" id="mode"></div>
<div class="pair"><figure><figcaption>Before</figcaption><img id="before" alt="Baseline terrain at the selected camera pose"></figure><figure><figcaption id="afterLabel">After</figcaption><img id="after" alt="Revised terrain at the identical camera pose"></figure></div>
<p class="legend"><span style="--c:#2dd269">Full</span><span style="--c:#f0dc2d">½ detail</span><span style="--c:#f07d28">¼ detail</span><span style="--c:#a546e6">⅛ detail</span></p>
<p class="small">Terrain-only Lambert diagnostic · 960 × 600 · identical fixed cameras. Reductions combine distance LOD and patch frustum culling. Draw calls are also at or below the original pre-quantization baseline. No FPS claim.</p>
<script>const data=DATA,images=IMAGES;let map=0,pose=1,overlay=false;const fmt=x=>x.toLocaleString('en-US'),saved=p=>(100*(1-p.triA/p.triB)).toFixed(1)+'%';
document.querySelector('#summary').innerHTML=data.map(d=>`<tr><td>${d.id}</td><td><strong>${saved(d.poses[1])}</strong></td><td><strong>${saved(d.poses[2])}</strong></td><td>${d.heapB.toFixed(1)} → <strong>${d.heapA.toFixed(1)}</strong></td><td>${d.gpu.toFixed(2)}</td></tr>`).join('');
function buttons(id,labels,selected,change){const box=document.getElementById(id);box.replaceChildren(...labels.map((label,i)=>{const b=document.createElement('button');b.textContent=label;b.setAttribute('aria-pressed',i===selected);b.onclick=()=>{change(i);render()};return b}));}
function render(){const d=data[map],p=d.poses[pose],im=images[d.id][p.name];buttons('maps',data.map(d=>d.id[0].toUpperCase()+d.id.slice(1)),map,i=>map=i);buttons('poses',['Start line','Mid-route','Overview'],pose,i=>pose=i);buttons('mode',['Surface comparison','LOD overlay'],+overlay,i=>overlay=!!i);document.getElementById('metric').innerHTML=`<strong>${fmt(p.triB)} → ${fmt(p.triA)} triangles</strong> · ${saved(p)} fewer<br>Draw calls: ${p.callsB} → <strong>${p.callsA}</strong>`;document.getElementById('before').src=im.before;document.getElementById('after').src=overlay?im.overlay:im.after;document.getElementById('afterLabel').textContent=overlay?'After · LOD colours':'After';}
render();console.log('Validated 3 maps, 9 poses and 27 images');</script></body></html>'''.replace('DATA',json.dumps(data)).replace('IMAGES',json.dumps(images))
(p/'lod2-comparison.html').write_text(html)
